import{_ as t,o,c as a,a2 as r}from"./chunks/framework.e4u2V5E7.js";const m=JSON.parse('{"title":"Performance","description":"Performance reference documentation","frontmatter":{"title":"Performance","description":"Performance reference documentation"},"headers":[],"relativePath":"knowledge/performance.md","filePath":"knowledge/performance.md","lastUpdated":1784485118000}'),n={name:"knowledge/performance.md"};function i(s,e,l,c,d,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h1><h1 id="web-performance-—-knowledge-base" tabindex="-1">Web Performance — Knowledge Base <a class="header-anchor" href="#web-performance-—-knowledge-base" aria-label="Permalink to &quot;Web Performance — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Web performance directly impacts user experience, conversion rates, and SEO rankings. This knowledge base covers Core Web Vitals, optimization strategies, and practical techniques for building fast Next.js applications that score well on Lighthouse and provide excellent user experiences.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="core-web-vitals" tabindex="-1">Core Web Vitals <a class="header-anchor" href="#core-web-vitals" aria-label="Permalink to &quot;Core Web Vitals&quot;">​</a></h3><p>Google&#39;s Core Web Vitals are the primary metrics for measuring user experience:</p><p><strong>Largest Contentful Paint (LCP)</strong> Measures loading performance. The largest visible element should render within 2.5 seconds of page load.</p><ul><li>Target: ≤ 2.5 seconds</li><li>Factors: server response time, resource load speed, render delay</li></ul><p><strong>First Input Delay (FID) / Interaction to Next Paint (INP)</strong> Measures interactivity. FID measures time from first interaction to browser response. INP (replacing FID in 2024) measures responsiveness throughout the session.</p><ul><li>Target: INP ≤ 200ms</li><li>Factors: main thread blocking time, JavaScript execution time</li></ul><p><strong>Cumulative Layout Shift (CLS)</strong> Measures visual stability. Unexpected layout shifts that occur during page lifecycle.</p><ul><li>Target: ≤ 0.1</li><li>Factors: images without dimensions, dynamically injected content, web fonts causing FOIT/FOUT</li></ul><h3 id="loading-optimization" tabindex="-1">Loading Optimization <a class="header-anchor" href="#loading-optimization" aria-label="Permalink to &quot;Loading Optimization&quot;">​</a></h3><p><strong>Code Splitting</strong> Breaking JavaScript bundles into smaller chunks loaded on demand. Next.js does this automatically per route with App Router.</p><p><strong>Lazy Loading</strong> Deferring loading of non-critical resources until they&#39;re needed. Images, below-the-fold content, and non-essential components.</p><p><strong>Prefetching</strong> Loading resources before they&#39;re needed. Next.js Link component prefetches pages by default. Use <code>next/dynamic</code> for component-level code splitting.</p><h3 id="caching-strategies" tabindex="-1">Caching Strategies <a class="header-anchor" href="#caching-strategies" aria-label="Permalink to &quot;Caching Strategies&quot;">​</a></h3><p><strong>Browser Cache:</strong> HTTP cache headers (<code>Cache-Control</code>, <code>ETag</code>, <code>Last-Modified</code>) <strong>CDN Cache:</strong> Edge caching for static assets and server-rendered pages <strong>Application Cache:</strong> In-memory or Redis caching for database queries <strong>Service Worker Cache:</strong> Offline-first caching for progressive web apps</p><h3 id="image-optimization" tabindex="-1">Image Optimization <a class="header-anchor" href="#image-optimization" aria-label="Permalink to &quot;Image Optimization&quot;">​</a></h3><p><strong>Next.js Image component</strong> provides:</p><ul><li>Automatic WebP/AVIF conversion</li><li>Responsive sizes with <code>srcset</code></li><li>Lazy loading by default (except above-the-fold)</li><li>Blur placeholder for perceived performance</li><li>Prevention of Cumulative Layout Shift with automatic sizing</li></ul><h3 id="compression" tabindex="-1">Compression <a class="header-anchor" href="#compression" aria-label="Permalink to &quot;Compression&quot;">​</a></h3><p><strong>Brotli</strong> — Better compression ratio than gzip; supported by all modern browsers <strong>Gzip</strong> — Universal fallback; supported everywhere <strong>Static asset optimization</strong> — Minification, tree-shaking, dead code elimination</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Use Next.js Image component</strong> — Always use <code>next/image</code> instead of <code>&lt;img&gt;</code>; it handles optimization, lazy loading, and prevents CLS automatically</li><li><strong>Implement dynamic imports for heavy components</strong> — Use <code>next/dynamic</code> with <code>{ ssr: false }</code> for components that don&#39;t need server rendering</li><li><strong>Optimize fonts with next/font</strong> — Use <code>next/font</code> for automatic font optimization; it self-hosts fonts and preloads them, eliminating FOUT/FOIT</li><li><strong>Minimize JavaScript bundle size</strong> — Analyze with <code>@next/bundle-analyzer</code>; remove unused dependencies; prefer lightweight alternatives</li><li><strong>Use Server Components by default</strong> — React Server Components send zero JavaScript to the client; only use <code>&quot;use client&quot;</code> when interactivity is needed</li><li><strong>Implement proper caching headers</strong> — Set <code>Cache-Control: s-maxage=31536000, immutable</code> for static assets; shorter TTLs for dynamic content</li><li><strong>Preload critical resources</strong> — Use <code>&lt;link rel=&quot;preload&quot;&gt;</code> for above-the-fold images, critical CSS, and fonts</li><li><strong>Monitor performance continuously</strong> — Use Vercel Analytics, Lighthouse CI, and real user monitoring (RUM) to track Core Web Vitals</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Using <code>&lt;img&gt;</code> instead of <code>next/image</code></strong> — Loses automatic optimization, lazy loading, and CLS prevention; always use the Image component</li><li><strong>Importing entire libraries for one function</strong> — <code>import _ from &#39;lodash&#39;</code> imports all functions; use <code>lodash-es</code> or <code>lodash/functionName</code> for tree-shaking</li><li><strong>Client-side rendering everything</strong> — Using <code>&quot;use client&quot;</code> on every component defeats Server Components; keep server rendering as the default</li><li><strong>Ignoring large bundle sizes</strong> — Not monitoring bundle growth allows gradual performance degradation; track bundle size in CI</li><li><strong>Unoptimized images</strong> — Serving original-resolution PNGs wastes bandwidth; always compress and serve modern formats</li><li><strong>Synchronous heavy computations on main thread</strong> — Long tasks block interactivity; use Web Workers, <code>requestIdleCallback</code>, or server-side processing</li><li><strong>Missing loading states</strong> — No loading indicators during navigation or data fetching makes the app feel slow; add skeleton screens and transitions</li><li><strong>Not using streaming SSR</strong> — Next.js supports streaming; returning large responses blocks rendering for all content</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Not setting image width and height</strong> — Causes Cumulative Layout Shift; always specify dimensions or use <code>fill</code> with a container</li><li><strong>Loading third-party scripts synchronously</strong> — Analytics, chat widgets, and ads block rendering; use <code>next/script</code> with <code>strategy=&quot;lazyOnload&quot;</code></li><li><strong>Ignoring Core Web Vitals in development</strong> — Performance issues compound; measure early and fix regressions immediately</li><li><strong>Over-caching dynamic content</strong> — CDN caching user-specific content serves stale data to wrong users; use <code>Cache-Control: private</code> for personalized pages</li><li><strong>Not using Suspense boundaries</strong> — Without Suspense, the entire page blocks until all data loads; wrap slow components in Suspense with fallbacks</li><li><strong>Excessive state management</strong> — Large global stores cause re-renders; minimize state scope and use React.memo for expensive components</li><li><strong>Forgetting about mobile performance</strong> — Mobile devices have slower CPUs and networks; test on throttled connections and low-end devices</li><li><strong>Not implementing pagination</strong> — Loading thousands of records at once kills performance; paginate all list endpoints</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric Concern</th><th>Optimization Strategy</th></tr></thead><tbody><tr><td>Slow LCP</td><td>Optimize server response, compress images, preload critical resources</td></tr><tr><td>High CLS</td><td>Add image dimensions, stabilize dynamic content, use font-display: swap</td></tr><tr><td>Poor INP</td><td>Reduce JavaScript execution, code-split heavy components, use Web Workers</td></tr><tr><td>Large bundles</td><td>Remove unused code, use dynamic imports, analyze with bundle analyzer</td></tr><tr><td>Slow API responses</td><td>Add database indexes, implement caching, use streaming responses</td></tr><tr><td>Slow mobile experience</td><td>Optimize for low-end devices, reduce JavaScript, use responsive images</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Web Vitals: <a href="https://web.dev/vitals/" target="_blank" rel="noreferrer">https://web.dev/vitals/</a></li><li>Next.js Performance: <a href="https://nextjs.org/docs/app/building-your-application/optimizing" target="_blank" rel="noreferrer">https://nextjs.org/docs/app/building-your-application/optimizing</a></li><li>Lighthouse: <a href="https://developer.chrome.com/docs/lighthouse/" target="_blank" rel="noreferrer">https://developer.chrome.com/docs/lighthouse/</a></li><li>Vercel Analytics: <a href="https://vercel.com/analytics" target="_blank" rel="noreferrer">https://vercel.com/analytics</a></li><li>Bundle Analyzer: <a href="https://www.npmjs.com/package/@next/bundle-analyzer" target="_blank" rel="noreferrer">https://www.npmjs.com/package/@next/bundle-analyzer</a></li><li>React.dev Performance: <a href="https://react.dev/learn" target="_blank" rel="noreferrer">https://react.dev/learn</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>Lighthouse CI:</strong> Integrate into GitHub Actions; set performance budget (score ≥ 90) and fail builds on regression</li><li><strong>Vercel Analytics:</strong> Automatically tracks Core Web Vitals; monitor trends and set alerts for degradation</li><li><strong>Image pipeline:</strong> Use Supabase Storage for image hosting; generate multiple sizes on upload; serve via CDN</li><li><strong>Font strategy:</strong> Use <code>next/font</code> with Google Fonts; self-host for performance; limit to 2 font families maximum</li><li><strong>Performance budget:</strong> Set bundle size limits in CI: 200KB initial JS, 50KB per route chunk, 100KB total CSS</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',38)])])}const h=t(n,[["render",i]]);export{m as __pageData,h as default};
